package br.com.onda;
import java.util.*;import org.json.*;
/** Brazilian city names and coordinates are searched locally. No GPS or geocoding API. */
final class RadioCity {
 final String name,state,countryCode,country;final double latitude,longitude;
 static final double RADIUS_KM=50;
 RadioCity(String name,String state,String code,String country,double lat,double lon){this.name=clean(name,100);this.state=clean(state,100);this.country=clean(country,100);this.countryCode=code==null?"":code.toUpperCase(Locale.ROOT);if(this.name.isEmpty()||!this.countryCode.matches("[A-Z]{2}")||!coordinate(lat,lon))throw new IllegalArgumentException("Cidade inválida.");latitude=lat;longitude=lon;}
 private static String clean(String s,int max){String v=s==null?"":s.replaceAll("[\\p{Cntrl}\\s]+"," ").trim();return v.substring(0,Math.min(max,v.length()));}
 static boolean coordinate(double lat,double lon){return Double.isFinite(lat)&&Double.isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180;}
 double distance(double lat,double lon){if(!coordinate(lat,lon))return Double.POSITIVE_INFINITY;double a=Math.toRadians(latitude),b=Math.toRadians(lat),dl=Math.toRadians(lat-latitude),dn=Math.toRadians(lon-longitude);double h=Math.sin(dl/2)*Math.sin(dl/2)+Math.cos(a)*Math.cos(b)*Math.sin(dn/2)*Math.sin(dn/2);return 12742*Math.asin(Math.sqrt(Math.max(0,Math.min(1,h))));}
 String label(){return name+(state.isEmpty()||state.equalsIgnoreCase(name)?"":" • "+state)+" • "+(country.isEmpty()?countryCode:country);}
 String key(){return countryCode+":"+Math.round(latitude*10000)+":"+Math.round(longitude*10000);}
 JSONObject json()throws JSONException{return new JSONObject().put("name",name).put("state",state).put("code",countryCode).put("country",country).put("lat",latitude).put("lon",longitude);}
 static RadioCity decode(String value){try{JSONObject o=new JSONObject(value);return new RadioCity(o.optString("name"),o.optString("state"),o.optString("code"),o.optString("country"),o.getDouble("lat"),o.getDouble("lon"));}catch(Exception e){return null;}}
 static String write(List<RadioCity> cities){JSONArray a=new JSONArray();for(RadioCity c:cities)if(a.length()<10)try{a.put(c.json());}catch(JSONException ignored){}return a.toString();}
 static List<RadioCity> read(String raw){ArrayList<RadioCity> out=new ArrayList<>();try{JSONArray a=new JSONArray(raw);for(int i=0;i<Math.min(10,a.length());i++){RadioCity c=decode(a.getJSONObject(i).toString());if(c!=null)out.add(c);}}catch(Exception ignored){}return out;}
 static List<RadioCity> local(String raw,String term)throws JSONException{String query=SearchText.normalize(term);if(query.isEmpty())return Collections.emptyList();String[] words=query.split(" ");JSONArray rows=new JSONArray(raw);ArrayList<RadioCity> found=new ArrayList<>();Map<String,Integer> score=new HashMap<>();for(int i=0;i<rows.length();i++)try{JSONArray row=rows.getJSONArray(i);String name=row.getString(0),state=row.getString(1),uf=row.getString(2),haystack=SearchText.normalize(name+" "+state+" "+uf);boolean match=true;for(String word:words)if(!haystack.contains(word)){match=false;break;}if(!match)continue;RadioCity city=new RadioCity(name,state,"BR","Brasil",row.getDouble(3),row.getDouble(4));String n=SearchText.normalize(name);int rank=n.equals(query)?0:n.startsWith(query)?1:2;score.put(city.key(),rank*2+(row.optInt(5)==1?0:1));found.add(city);}catch(Exception ignored){}found.sort(Comparator.comparingInt((RadioCity c)->score.get(c.key())).thenComparing(c->SearchText.normalize(c.name)).thenComparing(c->c.state));return new ArrayList<>(found.subList(0,Math.min(10,found.size())));}
}
